node -e '
import("/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs").then(async ({load}) => {
  const g = load("build.nbt");
  for (const c of [[26,3,12],[27,3,12],[26,3,10],[26,3,11]]) console.log(c.join(","), JSON.stringify(g.get ? g.get(...c) : g.at?.(...c)));
}).catch(e=>console.error(e.message));
' 2>&1 | head -20; grep -n "26,3,12\|26, 3, 12" parts-report.json | head; grep -rn "hearth_nook\|furnace" parts/*.mjs | grep -v room- | head

